import random

# Bigram table: P(next | current), learned from counting text.
P = {
    "the": {"cat": 0.5, "dog": 0.3, "end": 0.2},
    "cat": {"sat": 0.6, "ran": 0.4},
    "dog": {"ran": 0.7, "sat": 0.3},
    "sat": {"end": 1.0}, "ran": {"end": 1.0},
}

def generate(start, greedy, seed=0):
    random.seed(seed)
    out = [start]
    while out[-1] != "end":
        options = P[out[-1]]                        # context = last token only.
        if greedy:
            nxt = max(options, key=options.get)     # always the likeliest.
        else:
            nxt = random.choices(list(options), weights=options.values())[0]
        out.append(nxt)
    return " ".join(out)

print(generate("the", greedy=True))                  # the cat sat end
print([generate("the", greedy=False, seed=s) for s in (1, 2, 3)])
